//! Shared game preparation writes generated bytes to a native cache or worker memory.
use crate::source::ReadAssets;
use anyhow::{Context, Result};
use std::{collections::BTreeMap, path::Path};

/// Generated paths are relative to the cache, never to the original installation.
pub(crate) trait Output {
    fn read(&self, path: &Path) -> Option<Vec<u8>>;
    fn exists(&self, path: &Path) -> bool;
    fn remove(&mut self, path: &Path) -> Result<()>;
    fn publish(&mut self, path: &Path, bytes: &[u8]) -> Result<()>;
    fn image(&mut self, path: &Path, image: &image::RgbaImage) -> Result<()> {
        let mut bytes = std::io::Cursor::new(Vec::new());
        image.write_to(&mut bytes, image::ImageFormat::Png)?;
        self.publish(path, &bytes.into_inner())
    }
}

impl Output for BTreeMap<String, Vec<u8>> {
    fn read(&self, path: &Path) -> Option<Vec<u8>> {
        self.get(&generated_path(path).ok()?).cloned()
    }
    fn exists(&self, path: &Path) -> bool {
        generated_path(path).is_ok_and(|path| self.contains_key(&path))
    }
    fn remove(&mut self, path: &Path) -> Result<()> {
        self.remove(&generated_path(path)?);
        Ok(())
    }
    fn publish(&mut self, path: &Path, bytes: &[u8]) -> Result<()> {
        self.insert(generated_path(path)?, bytes.to_vec());
        Ok(())
    }
}

fn generated_path(path: &Path) -> Result<String> {
    let path = path
        .to_str()
        .context("generated path is not UTF-8")?
        .replace('\\', "/");
    crate::validate_path(&path)?;
    Ok(path)
}

/// Resolve authored DOS paths against the validated, case-insensitive source manifest.
pub(crate) fn path(source: &dyn ReadAssets, name: &str) -> Result<String> {
    let name = name.replace('\\', "/");
    crate::validate_path(&name)?;
    let software = software_name(&name);
    source
        .manifest()
        .find(&name)
        .or_else(|| {
            software
                .as_deref()
                .and_then(|name| source.manifest().find(name))
        })
        .map(|file| file.path.clone())
        .with_context(|| format!("missing original file {name}"))
}

/// The software install's name for a Glide art file: `fxart/X` is `3dart/X`, and `TEXBSI.###`
/// banks are `TEXTURE.###`.
fn software_name(name: &str) -> Option<String> {
    let rest = name
        .strip_prefix("fxart/")
        .or_else(|| name.strip_prefix("FXART/"))?;
    let upper = rest.to_ascii_uppercase();
    Some(match upper.strip_prefix("TEXBSI.") {
        Some(id) => format!("3dart/TEXTURE.{id}"),
        None => format!("3dart/{rest}"),
    })
}

/// One texture bank's images by image index, in either edition's format.
pub(crate) struct Bank {
    raw: Vec<u8>,
    images: Vec<(rgpre::import::bsi::BsiImage, bool)>,
}

impl std::hash::Hash for Bank {
    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
        self.raw.hash(state);
    }
}

impl Bank {
    /// Reads `fxart/TEXBSI.<id>`, or the software install's `3dart/TEXTURE.<id>`.
    pub(crate) fn read(source: &dyn ReadAssets, id: u16) -> Result<Self> {
        let name = format!("fxart/TEXBSI.{id:03}");
        let bytes = read(source, &name)?;
        Self::parse(
            &bytes,
            path(source, &name)?
                .to_ascii_uppercase()
                .contains("/TEXTURE."),
        )
        .with_context(|| format!("texture bank {id:03}"))
    }
    pub(crate) fn parse(bytes: &[u8], software: bool) -> Result<Self> {
        let images = if software {
            rgpre::import::software_texture::parse_texture_bank(bytes)?.into_bsi_images()
        } else {
            rgpre::import::bsi::parse_bsi_file(bytes)?
                .images
                .into_iter()
                .map(|image| (image, true))
                .collect()
        };
        Ok(Self {
            raw: bytes.to_vec(),
            images,
        })
    }
    /// Images with their index, in bank order.
    pub(crate) fn iter(&self) -> impl Iterator<Item = (u16, &rgpre::import::bsi::BsiImage)> {
        self.images
            .iter()
            .map(|(image, _)| (image.image_index, image))
    }
    pub(crate) fn get(&self, index: u16) -> Option<&rgpre::import::bsi::BsiImage> {
        self.images
            .iter()
            .map(|(image, _)| image)
            .find(|image| image.image_index == index)
    }
    /// RGBA of frame zero; software records without the transparency flag are fully opaque.
    pub(crate) fn rgba(
        &self,
        index: u16,
        palette: &rgpre::import::palette::Palette,
    ) -> Option<Vec<u8>> {
        let (image, transparent) = self
            .images
            .iter()
            .find(|(image, _)| image.image_index == index)?;
        let mut rgba = image.decode_rgba(Some(palette));
        if !transparent {
            rgba.chunks_exact_mut(4).for_each(|pixel| pixel[3] = 255);
        }
        Some(rgba)
    }
}

pub(crate) fn read(source: &dyn ReadAssets, name: &str) -> Result<Vec<u8>> {
    source.read(&path(source, name)?)
}

pub(crate) fn text(source: &dyn ReadAssets, name: &str) -> Result<String> {
    source.text(&path(source, name)?)
}

pub(crate) fn soup(source: &dyn ReadAssets) -> Result<rgpre::import::soup_def::SoupDef> {
    rgpre::import::soup_def::parse_soup_def(&text(source, "soup386/SOUP386.DEF")?)
        .map_err(anyhow::Error::msg)
        .context("soup386/SOUP386.DEF")
}

#[cfg(all(feature = "native", not(target_arch = "wasm32")))]
pub(crate) struct DiskOutput<'a>(pub &'a Path);
#[cfg(all(feature = "native", not(target_arch = "wasm32")))]
impl Output for DiskOutput<'_> {
    fn read(&self, path: &Path) -> Option<Vec<u8>> {
        std::fs::read(self.0.join(generated_path(path).ok()?)).ok()
    }
    fn exists(&self, path: &Path) -> bool {
        generated_path(path).is_ok_and(|path| self.0.join(path).is_file())
    }
    fn remove(&mut self, path: &Path) -> Result<()> {
        let path = self.0.join(generated_path(path)?);
        if path.is_file() {
            std::fs::remove_file(path)?;
        }
        Ok(())
    }
    fn publish(&mut self, path: &Path, bytes: &[u8]) -> Result<()> {
        crate::native::publish(&self.0.join(generated_path(path)?), bytes)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn nested_output_round_trip(output: &mut dyn Output) {
        let windows = Path::new(r"sounds\000.wav");
        let portable = Path::new("sounds/000.wav");
        output.publish(windows, b"audio").unwrap();
        assert_eq!(output.read(portable).as_deref(), Some(b"audio".as_slice()));
        assert!(output.exists(windows));
        output.remove(windows).unwrap();
        assert!(!output.exists(portable));
        for invalid in [
            r"..\outside.wav",
            r"C:\outside.wav",
            r"\outside.wav",
            "sounds/../outside.wav",
        ] {
            assert!(output.publish(Path::new(invalid), b"audio").is_err());
        }
    }

    #[test]
    fn memory_output_uses_portable_paths_for_windows_generated_assets() {
        let mut files = BTreeMap::new();
        nested_output_round_trip(&mut files);
        assert!(files.is_empty());
    }

    #[cfg(all(feature = "native", not(target_arch = "wasm32")))]
    #[test]
    fn disk_output_accepts_windows_generated_assets_without_allowing_escape() {
        let root = std::env::temp_dir().join(format!("cyrus-output-paths-{}", std::process::id()));
        nested_output_round_trip(&mut DiskOutput(&root));
        std::fs::remove_dir_all(root).unwrap();
    }
}
